require_once __DIR__.'/core.php';tt_require_login();if($_SERVER['REQUEST_METHOD']!=='POST'||!isset($_POST['enter'])){header('Location: usrchange.php');exit;}if((int)($_POST['test']??-1)!==((int)($_POST['no1']??0)+(int)($_POST['no2']??0)))tt_fail('Invalid captcha.',400,'Credentials');$db=tt_db_open(true);$id=(int)$_SESSION['id'];$current=(string)($_POST['password']??'');$newName=trim((string)($_POST['username2']??''));$newPass=(string)($_POST['password2']??'');$newEmail=trim((string)($_POST['email2']??''));if($newName===''||strlen($newName)>50||!filter_var($newEmail,FILTER_VALIDATE_EMAIL))tt_fail('Enter a valid username and email.',400,'Credentials');$s=tt_prepare($db,'SELECT `password` FROM `accounts` WHERE `id`=?');$s->bind_param('i',$id);$s->execute();$s->bind_result($hash);if(!$s->fetch()){$s->close();$db->close();tt_fail('Account not found.',404,'Credentials');}$s->close();if(!password_verify($current,(string)$hash)){$db->close();tt_fail('Current password is incorrect.',400,'Credentials');}$s=tt_prepare($db,'SELECT `id` FROM `accounts` WHERE `username`=? AND `id`<>? LIMIT 1');$s->bind_param('si',$newName,$id);$s->execute();$s->store_result();if($s->num_rows){$s->close();$db->close();tt_fail('That username is already in use.',400,'Credentials');}$s->close();if($newPass!==''){$newHash=password_hash($newPass,PASSWORD_DEFAULT);$s=tt_prepare($db,'UPDATE `accounts` SET `username`=?,`password`=?,`email`=? WHERE `id`=?');$s->bind_param('sssi',$newName,$newHash,$newEmail,$id);}else{$s=tt_prepare($db,'UPDATE `accounts` SET `username`=?,`email`=? WHERE `id`=?');$s->bind_param('ssi',$newName,$newEmail,$id);}if(!$s->execute()){$e=$s->error;$s->close();$db->close();tt_fail('Could not update credentials: '.$e,503,'Credentials');}$s->close();$_SESSION['name']=$newName;$db->close();header('Location: account.php?credentials=updated');exit;
